1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type Result = { premium: number } | { payout: number; remainingCap: number };
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
28	const CURSE_SURCHARGE_RATE = 0.5;
29	const HIGH_ENCHANTMENT_THRESHOLD = 5;
30	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
31	const LOYALTY_YEARS_THRESHOLD = 2;
32	const LOYALTY_DISCOUNT_RATE = 0.2;
33	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
34	
35	const BASE_PREMIUMS: Record<string, number> = {
36	  sword: 100,
37	  amulet: 60,
38	  staff: 80,
39	  potion: 40,
40	  rune: 25,
41	  moonstone: 25,
42	};
43	
44	const BLOCK_SIZE = 3;
45	const BLOCK_PREMIUM = 60;
46	
47	/** Items that share the same `type`, and so are priced together. */
48	type AlikeItems = Item[];
49	
50	const groupAlikeItems = (items: Item[]): AlikeItems[] => {
51	  const byType = new Map<string, AlikeItems>();
52	  items.forEach((item) => byType.set(item.type, [...(byType.get(item.type) ?? []), item]));
53	  return [...byType.values()];
54	};
55	
56	const formsBlock = (items: AlikeItems): boolean => items.length === BLOCK_SIZE;
57	
58	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
59	
60	const alikeItemsBasePremium = (alikeItems: AlikeItems): number =>
61	  formsBlock(alikeItems)
62	    ? BLOCK_PREMIUM
63	    : alikeItems.reduce((total, item) => total + itemBasePremium(item), 0);
64	
65	const totalBasePremium = (items: Item[]): number =>
66	  groupAlikeItems(items).reduce((total, alikeItems) => total + alikeItemsBasePremium(alikeItems), 0);
67	
68	const isCursed = (item: Item): boolean => item.cursed === true;
69	
70	const isHighlyEnchanted = (item: Item): boolean =>
71	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
72	
73	/**
74	 * An item-specific surcharge: `rate` × the item's own base premium, charged
75	 * once per item the rule `applies` to. Never charged on the policy's base, so
76	 * every rule contributes an independent additive term.
77	 */
78	type ItemSurcharge = { applies: (item: Item) => boolean; rate: number };
79	
80	const ITEM_SURCHARGES: ItemSurcharge[] = [
81	  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
82	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
83	];
84	
85	const itemSurchargesFor = (item: Item): number =>
86	  ITEM_SURCHARGES.filter(({ applies }) => applies(item)).reduce(
87	    (total, { rate }) => total + itemBasePremium(item) * rate,
88	    0,
89	  );
90	
91	const totalItemSurcharges = (items: Item[]): number =>
92	  items.reduce((total, item) => total + itemSurchargesFor(item), 0);
93	
94	/**
95	 * A policy-wide modifier: `rate` × the policy's base premium, charged once per
96	 * quote. Like the item surcharges, each rule contributes an independent
97	 * additive term rather than compounding on earlier ones — so a discount is just
98	 * a negative `rate`, not a subtraction applied at some point in a sequence.
99	 */
100	type PolicyAdjustment = { applies: (policy: Policy) => boolean; rate: number };
101	
102	/** Everything a policy-wide rule may look at when deciding whether it applies. */
103	type Policy = { customer: Customer; priorContracts: number };
104	
105	/**
106	 * Always true: the MHPCO treats every item in a quote as newly insured, so the
107	 * surcharge applies even to a long-standing customer's follow-up contract.
108	 */
109	const isFirstInsurance = (_policy: Policy): boolean => true;
110	
111	const isLoyalCustomer = ({ customer }: Policy): boolean =>
112	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
113	
114	const isFollowUpContract = ({ priorContracts }: Policy): boolean => priorContracts > 0;
115	
116	const POLICY_ADJUSTMENTS: PolicyAdjustment[] = [
117	  { applies: isFirstInsurance, rate: FIRST_INSURANCE_SURCHARGE_RATE },
118	  { applies: isLoyalCustomer, rate: -LOYALTY_DISCOUNT_RATE },
119	  { applies: isFollowUpContract, rate: -FOLLOW_UP_DISCOUNT_RATE },
120	];
121	
122	const totalPolicyAdjustments = (base: number, policy: Policy): number =>
123	  POLICY_ADJUSTMENTS.filter(({ applies }) => applies(policy)).reduce(
124	    (total, { rate }) => total + base * rate,
125	    0,
126	  );
127	
128	const quotePremium = (items: Item[], policy: Policy): number => {
129	  const base = totalBasePremium(items);
130	  // Every term is added to `base`, never multiplied onto a running total. The
131	  // algebraically equivalent base * (1 + rate) yields 110.00000000000001 for
132	  // base 100, which Math.ceil turns into a premium that is 1 G too high.
133	  return Math.ceil(
134	    base + totalItemSurcharges(items) + totalPolicyAdjustments(base, policy) + PROCESSING_FEE,
135	  );
136	};
137	
138	const isQuote = (step: Step): boolean => step.op === "quote";
139	
140	/**
141	 * A contract is created by each quote, so the number the customer already held
142	 * when `stepIndex` is reached is just the number of quotes before it. Claims are
143	 * not contracts and so do not count.
144	 */
145	const priorContractsAt = (steps: Step[], stepIndex: number): number =>
146	  steps.slice(0, stepIndex).filter(isQuote).length;
147	
148	export const runScenario = (scenario: Scenario): Result[] =>
149	  scenario.steps.map((step, stepIndex) => {
150	    if (step.op === "quote") {
151	      const policy = {
152	        customer: scenario.customer,
153	        priorContracts: priorContractsAt(scenario.steps, stepIndex),
154	      };
155	      return { premium: quotePremium(step.items, policy) };
156	    }
157	    throw new Error(`Unsupported step: ${step.op}`);
158	  });
