/**
 * A policy-wide modifier: `rate` × the policy's base premium, charged once per
 * quote. Like the item surcharges, each rule contributes an independent
 * additive term rather than compounding on earlier ones — so a discount is just
 * a negative `rate`, not a subtraction applied at some point in a sequence.
 */
type PolicyAdjustment = { applies: (policy: Policy) => boolean; rate: number };

/** Everything a policy-wide rule may look at when deciding whether it applies. */
type Policy = { customer: Customer; priorContracts: number };

/**
 * Always true: the MHPCO treats every item in a quote as newly insured, so the
 * surcharge applies even to a long-standing customer's follow-up contract.
 */
const isFirstInsurance = (_policy: Policy): boolean => true;

const isLoyalCustomer = ({ customer }: Policy): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;

const isFollowUpContract = ({ priorContracts }: Policy): boolean => priorContracts > 0;

const POLICY_ADJUSTMENTS: PolicyAdjustment[] = [
  { applies: isFirstInsurance, rate: FIRST_INSURANCE_SURCHARGE_RATE },
  { applies: isLoyalCustomer, rate: -LOYALTY_DISCOUNT_RATE },
  { applies: isFollowUpContract, rate: -FOLLOW_UP_DISCOUNT_RATE },
];

const totalPolicyAdjustments = (base: number, policy: Policy): number =>
  POLICY_ADJUSTMENTS.filter(({ applies }) => applies(policy)).reduce(
    (total, { rate }) => total + base * rate,
    0,
  );

const quotePremium = (items: Item[], policy: Policy): number => {
  const base = totalBasePremium(items);
  // Every term is added to `base`, never multiplied onto a running total. The
  // algebraically equivalent base * (1 + rate) yields 110.00000000000001 for
  // base 100, which Math.ceil turns into a premium that is 1 G too high.
  return Math.ceil(
    base + totalItemSurcharges(items) + totalPolicyAdjustments(base, policy) + PROCESSING_FEE,
  );
};

